const DEMAND_LEDGER_BY_URL = new Map(DEMAND_LEDGER.map(row => [row.url, row]));
const DEMAND_LEDGER_BY_PRODUCT_ID = new Map(
  DEMAND_LEDGER.filter(row => row.product_id).map(row => [row.product_id, row]),
);

export function opportunityForUrl(url) {
  return DEMAND_LEDGER_BY_URL.get(String(url || '')) || null;
}

export function opportunityForProductId(id) {
  return DEMAND_LEDGER_BY_PRODUCT_ID.get(String(id || '').toUpperCase()) || null;
}

/** Top N filas con score positivo, ya vienen ordenadas por score desc. */
export function topOpportunities(limit = 20, { pageType } = {}) {
  const filtered = pageType
    ? DEMAND_LEDGER.filter(row => row.page_type === pageType)
    : DEMAND_LEDGER;
  return filtered.filter(row => (row.opportunity_score || 0) > 0).slice(0, limit);
}
